def _sanitize_diagnostic_hint(raw: Any) -> str | None:
    if not isinstance(raw, str):
        return None
    text = " ".join(raw.strip().split())
    if not text:
        return None
    low = text.lower()
    if any(marker in low for marker in _DIAG_SENSITIVE_MARKERS):
        return None
    return text[:240]


